		// 最终层：应用索引写成字符串，字段名首字母大写。
		`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FinalAppliedIndex":"9"}`,
		// 最终层：键值表写成数组，字段名全大写。
		`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FINALKV":["nope"]}`,
