func TestKVParseIncrCommands(t *testing.T) {
	cases := []struct {
		command    string
		wantOp     kvOperation
		wantReason string
	}{
		// incr 的增量合法性在应用时结合当前值判定：解析阶段只拆键与增量原文，
		// 空增量、缺等号也能解析成功，不产生格式错误。
		{"incr x=1", kvOperation{isIncr: true, key: "x", value: "1"}, ""},
